import React, { useState, useCallback } from 'react';
import './controller.css';

/**
 * Controller component - shown on the phone side
 * Mode 1: Send links to open on computer
 * Mode 2: Send notes to display on computer (presenter mode)
 */
function Controller({ connected, error, sendData }) {
    const [mode, setMode] = useState('link'); // 'link' or 'notes'
    const [linkValue, setLinkValue] = useState('');
    const [notesValue, setNotesValue] = useState('');
    const [sent, setSent] = useState(false);

    const handleLinkChange = useCallback((event) => {
        setLinkValue(event.target.value);
        setSent(false);
    }, []);

    const handleNotesChange = useCallback((event) => {
        setNotesValue(event.target.value);
    }, []);

    const handleLinkSubmit = useCallback((event) => {
        event.preventDefault();
        if (sendData({ type: 'link', url: linkValue })) {
            setSent(true);
            setLinkValue('');
        }
    }, [sendData, linkValue]);

    const handleNotesSend = useCallback(() => {
        if (sendData({ type: 'notes', text: notesValue })) {
            setSent(true);
            setTimeout(() => setSent(false), 2000);
        }
    }, [sendData, notesValue]);

    const handleClearNotes = useCallback(() => {
        sendData({ type: 'notes', text: '' });
        setNotesValue('');
    }, [sendData]);

    if (error) {
        return (
            <div className="controller-status">
                <div className="error">❌ 連線錯誤: {error}</div>
                <div className="intro">請重新掃描 QR Code</div>
            </div>
        );
    }

    if (!connected) {
        return (
            <div className="controller-status">
                <div className="connecting">🔄 正在連線到電腦...</div>
            </div>
        );
    }

    return (
        <div className="controller-container">
            <div className="controller-status">
                <span className="connected">✓ 已連線到電腦</span>
            </div>

            {/* Mode Tabs */}
            <div className="mode-tabs">
                <button
                    className={`mode-tab ${mode === 'link' ? 'active' : ''}`}
                    onClick={() => setMode('link')}
                >
                    🔗 開啟連結
                </button>
                <button
                    className={`mode-tab ${mode === 'notes' ? 'active' : ''}`}
                    onClick={() => setMode('notes')}
                >
                    📝 簡報筆記
                </button>
            </div>

            {/* Link Mode */}
            {mode === 'link' && (
                <form onSubmit={handleLinkSubmit}>
                    <div className="form__group field">
                        <input
                            type="url"
                            className="form__field"
                            placeholder="輸入網址"
                            name="Link"
                            id="link-input"
                            value={linkValue}
                            onChange={handleLinkChange}
                            required
                        />
                        <label htmlFor="link-input" className="form__label">
                            網址
                        </label>
                    </div>

                    {sent && (
                        <div className="sent-message">✓ 已發送！電腦將開啟連結</div>
                    )}

                    <br />
                    <button className="btn" type="submit" disabled={!linkValue}>
                        發送到電腦
                    </button>
                </form>
            )}

            {/* Notes Mode (Presenter) */}
            {mode === 'notes' && (
                <div className="notes-mode">
                    <textarea
                        className="notes-input"
                        placeholder="輸入筆記或註解，會顯示在電腦畫面上..."
                        value={notesValue}
                        onChange={handleNotesChange}
                    />

                    {sent && (
                        <div className="sent-message">✓ 筆記已同步</div>
                    )}

                    <div className="notes-buttons">
                        <button className="btn" type="button" onClick={handleNotesSend}>
                            📤 顯示筆記
                        </button>
                        <button
                            className="btn"
                            type="button"
                            onClick={handleClearNotes}
                            style={{ marginLeft: '0.5em', background: '#666' }}
                        >
                            🗑️ 清除
                        </button>
                    </div>
                </div>
            )}
        </div>
    );
}

export default Controller;
