import React, { useMemo } from 'react';
import QRCode from 'qrcode.react';
import { buildConnectionUrl } from '../utils/utils';

/**
 * Connector component - displays QR code for phone to scan
 * Shows connection status
 */
function Connector({ peerId, connected, error }) {
    const connectionUrl = useMemo(() => {
        return peerId ? buildConnectionUrl(peerId) : '';
    }, [peerId]);

    if (error) {
        return (
            <section id="banner" style={{ zIndex: -1, position: 'relative' }}>
                <div className="snapshare">
                    <img
                        height="100%"
                        alt="SnapShare Logo"
                        src="https://raw.githubusercontent.com/voidful/SnapShare/master/website/public/logo512.png"
                    />
                    <h2 className="intro">SnapShare</h2>
                </div>
                <div className="status error" style={{ background: 'rgba(255,0,0,0.1)', padding: '20px' }}>
                    <h3>⚠️ 連線錯誤</h3>
                    <p>{error}</p>
                    <p style={{ fontSize: '0.8em' }}>請確認網路狀態，或稍後再試</p>
                </div>
            </section>
        );
    }

    return (
        <section id="banner" style={{ zIndex: -1, position: 'relative' }}>
            <div className="snapshare">
                <img
                    height="100%"
                    alt="SnapShare Logo"
                    src="https://raw.githubusercontent.com/voidful/SnapShare/master/website/public/logo512.png"
                />
                <h2 className="intro">SnapShare</h2>
            </div>

            {peerId ? (
                <>
                    <QRCode value={connectionUrl} size={200} renderAs="svg" />
                    <div className="status">
                        {connected ? (
                            <span className="connected">✓ 手機已連線</span>
                        ) : (
                            <span className="waiting">等待手機掃描連線...</span>
                        )}
                    </div>
                </>
            ) : (
                <div className="intro">連線中...</div>
            )}

            <div className="intro">
                {"用手機掃描 QR Code\n貼上連結，電腦自動開啟"}
            </div>

            <footer>
                <a
                    href="https://github.com/voidful/SnapShare"
                    target="_blank"
                    rel="noopener noreferrer"
                >
                    <i className="icon-social-github icons" />
                </a>
            </footer>
        </section>
    );
}

export default Connector;
